cd /home/daytona/workspace && python3 -c "
import pandas as pd, numpy as np
df=pd.read_csv('data.csv')
ints=['pregnancies','glucose','blood_pressure','skin_thickness','insulin','age']
for bt,pt in [(0.05,0.005),(0.1,0.01),(0.2,0.02),(0.5,0.05)]:
    drop=set()
    for _,g in df.groupby(ints):
        if len(g)<2: continue
        idx=g.index.tolist()
        for i in range(len(idx)):
            for j in range(i+1,len(idx)):
                a,b=df.loc[idx[i]],df.loc[idx[j]]
                if abs(a.bmi-b.bmi)<=bt and abs(a.diabetes_pedigree-b.diabetes_pedigree)<=pt and a.outcome==b.outcome:
                    drop.add(idx[j])
    print(bt,pt,len(drop))
"
